from shiny import *
from ipyshiny import *
import ipyleaflet as leaf
from ipyleaflet import basemaps

app_ui = ui.page_fluid(
    ui.p("Zoom on the map then click the button...tiles don't update!!!"),
    ui.input_action_button("add_tiles", "Add tiles"),
    output_widget("map"),
)

def server(input: Inputs, output: Outputs, session: Session):

    map = leaf.Map(center=(37.45, -93.85), zoom=4)

    @output(name="map")
    @render_widget()
    def _():
        return map

    @reactive.Effect()
    @event(input.add_tiles)
    def _():
        map.add_layer(leaf.basemap_to_tiles(basemaps.CartoDB.DarkMatter))

